// darkest-to-lightest surfaces it can appear on. Edit with care; see src/lib/themeEngine.ts for how they are applied.
export type RGB = [number, number, number];

export interface ThemeDef {
  id: string;
  name: string;
  /** CSS custom properties (space-separated RGB triplets), animated by the engine */
  vars: Record<string, RGB>;
  /** colours used by the canvas particle network */
  canvas: RGB[];
  /** browser UI colour (mobile address bar) */
  meta: string;
  /** three colours for the picker swatch */
  swatch: [string, string, string];
}

